function nulkaAuto15B(){
 const r=skRuntime15B('NULKA'),p=skSpec15B('NULKA'),period=Math.max(1,Math.round(1/p.autoCheckHz/SIM_FIXED_DT));
 if(!softKillAutoDoctrine||simStepCounter-r.lastAutoCheckStep<period)return;r.lastAutoCheckStep=simStepCounter;
 if((simStepCounter-r.lastAutoStep)*SIM_FIXED_DT<p.autoIntervalS)return;
 for(const th of softKillThreatState.threats){
  if(nulkaCueError15B(th))continue;const key=String(softKillResponseIdentity(th)??th.key??'');
  const last=r.responses[key];if(last&&(simStepCounter-last.step)*SIM_FIXED_DT<p.autoSameCueIntervalS)continue;
  // Coverage is only a launch-time spatial/time budget, NOT knowledge of an enemy seeker's lock.
  if(r.history.some(h=>(simStepCounter-h.step)*SIM_FIXED_DT<p.autoSameCueIntervalS&&Math.abs(angNorm(h.bearing-th.bearing))<deg(p.autoCoverageDeg)))continue;
  const fired=nulkaFire15B(th,{automatic:true});if(fired.ok){r.lastAutoStep=simStepCounter;r.responses[key]={step:simStepCounter};break;}
 }
 for(const [k,v]of Object.entries(r.responses))if((simStepCounter-v.step)*SIM_FIXED_DT>180)delete r.responses[k];
}

