function nulkaCueError15B(th){
 const p=skSpec15B('NULKA');if(!th||!Number.isFinite(th.bearing))return 'NO_VALID_ASM_BEARING';
 if(!Number.isFinite(th.freshnessS)||th.freshnessS<0||th.freshnessS>p.cueMaxAgeS)return 'STALE_BEARING';
 if(!Number.isFinite(th.bearingSigmaDeg)||th.bearingSigmaDeg<0||th.bearingSigmaDeg>p.cueMaxSigmaDeg)return 'BEARING_QUALITY';
 if(!Number.isFinite(th.activeSeekerConfidence)||!Number.isFinite(th.missileLikeConfidence)||th.activeSeekerConfidence<p.minActiveConfidence||th.missileLikeConfidence<p.minMissileConfidence)return 'NO_ACTIVE_SEEKER_EVIDENCE';
 if(th.trackId!=null){const tr=tracks.get(th.trackId);if(!tr)return 'TRACK_LOST';
  if(['FRIEND','NEUTRAL'].includes(tr.identity)||['KILL_ASSESSMENT','DESTROYED','HARMLESS'].includes(tr.threatStatus))return 'TRACK_NOT_THREAT';}
 return null;
}

