function deployOwnChaffForThreat(threat,opts={}){
    if(shipEquipmentOfflineV1()){if(!opts.automatic)notify('채프 발사 차단 · 장비 정지');return 0;}
    const automatic=!!opts.automatic;
    if(MK36_RUNTIME_WIP15A.cooldownS>0){ if(!automatic)notify(`Mk 36 SRBOC 대기 ${(MK36_RUNTIME_WIP15A.cooldownS).toFixed(1)}s`); return 0; }
    if(mk36LoadedRounds()<=0){ if(!automatic)notify('Mk 36 SRBOC — 발사관 탄약 없음'); return 0; }
    const threatBearing=threat?.bearing ?? shipNav.heading;
    mk36LastCue={step:simStepCounter,key:softKillThreatKey(threat),source:automatic?'AUTO_DOCTRINE':(threat?.source??'MANUAL_FALLBACK'),bearing:threatBearing,responseId:opts.responseId??null};
    let fired=0;
    for(let i=0;i<MK36_SRBOC.salvoRounds;i++){
      const l=mk36SelectLauncher(threatBearing); if(!l) break;
      if(mk36FireRound(l,threatBearing,i)) fired++;
    }
    if(!fired){if(!automatic)notify('Mk 36 SRBOC — 사용 가능한 발사관 없음');return 0;}
    MK36_RUNTIME_WIP15A.cooldownS=MK36_SRBOC.salvoCooldownS; updateMk36ButtonLabel();
    notify(`${automatic?'AUTO ':''}Mk 36 SRBOC — Mk 214 ${fired}발 발사 / 잔탄 ${mk36LoadedRounds()}`);
    return fired;
  }

