function notify(msg){
    const safeMsg=sanitizeEngagementDisplayText(msg);
    // Player-visible debug/toast stream uses the same sanitized presentation boundary.
    debugLog(safeMsg);
    const el = document.createElement('div');
    el.className = 'toast';
    el.textContent = safeMsg;
    toastWrap.prepend(el);
    requestAnimationFrame(()=> el.classList.add('show'));
    setTimeout(()=> {
      el.classList.remove('show');
      setTimeout(()=> el.remove(), 220);
    }, 2200);
    while(toastWrap.children.length > 4){
      toastWrap.lastChild?.remove();
    }
  }

