function mk36SelectLauncher(threatBearing){
    if(!Number.isFinite(threatBearing)||shipEquipmentOfflineV1())return null;
    // Same nearest-bearing selection idea as B4, now applied to real available bores.
    // Equal-bearing ties have stable profile order; there is no hidden swivel/spread offset.
    let best=null,bestError=Infinity;
    for(const l of mk36LauncherState){
      if(!mk36LauncherAvailableWip15A(l))continue;
      const h=mk36MountWip15A(l.id),t=h.tubes[mk36NextTubeWip15A(l)];if(!mk36TubeSectorWip15A(h,t))continue;
      const e=Math.abs(angNorm(threatBearing-mk36LauncherBearing(l)));
      if(e<bestError-1e-9){best=l;bestError=e;}
    }
    return best;
  }
